 static List<ProtoLite.EntityMessage>frames(byte[]wire)throws IOException{List<ProtoLite.EntityMessage>all=new ArrayList<>();ByteBuffer b=ByteBuffer.wrap(wire).order(ByteOrder.LITTLE_ENDIAN);while(b.hasRemaining()){int len=b.getInt();check(b.getShort()==5,"opcode");byte[]msg=new byte[len-2];b.get(msg);all.add(ProtoLite.parseEntityMessage(msg));}return all;}
